FILE scripts\3_Game\LFPG_Migrators.c
1: // =========================================================
2: // LF_PowerGrid - persistence schema migrators (v0.7.15, Sprint 3 P1)
3: //
4: // Legacy version helpers: apply the v1 -> v2 bump without changing wire fields.
5: // Newer schema versions are returned unchanged; validation belongs to loaders.
6: //
7: // Migration chain:
8: //   v1 (original) → v2 (Sprint 3: infrastructure + sanitization)
9: //   v2 → v3 (Sprint 4: reserved for graph model fields)
10: //
11: // =========================================================
12: // COMPATIBILITY STRATEGY for Sprint 4 (grafo):
13: //
14: // The electrical graph is an IN-MEMORY structure reconstructed from wires
15: // on server startup. Wires remain the persisted source of truth.
16: //
17: // Sprint 4 may add optional fields to LFPG_WireData:
18: //   - m_Priority (int): wire priority for load allocation (default: 0)
19: //   - m_Flags (int): bitfield for future states (default: 0)
20: //
21: // Migrator v2→v3 will:
22: //   - Set m_Priority = 0 for all existing wires (preserves behavior)
23: //   - Set m_Flags = 0 for all existing wires
24: //
25: // Rollback policy:
26: //   - v3 data loaded by v2 code: unknown fields ignored by JsonFileLoader
27: //   - v2 data loaded by v3 code: migrator fills defaults
28: //   - v1 data loaded by any version: migrator chain applies (v1→v2→v3)
29: //
30: // What is persisted vs reconstructed:
31: //   PERSISTED: wire endpoints, ports, waypoints, creator, priority, flags
32: //   RECONSTRUCTED: graph topology, power states, load ratios, overload masks
33: // =========================================================
34: 
35: class LFPG_Migrators
36: {
37: 	// Apply the legacy version bump without validating or rewriting wire fields.
38: 	// Returns the version; newer schemas are left unchanged.
39:     static int MigrateBlob(LFPG_PersistBlob blob)
40:     {
41:         if (!blob)
42:             return LFPG_PERSIST_VER;
43: 
44:         int ver = blob.ver;
45: 
46:         // Unknown future version: load tolerantly, don't migrate down
47:         if (ver > LFPG_PERSIST_VER)
48:         {
49:             LFPG_Util.Warn("[Migrators] Blob ver " + ver.ToString() + " > current " + LFPG_PERSIST_VER.ToString() + ". Loading tolerantly (no downgrade).");
50:             return ver;
51:         }
52: 
53: 		// v1 -> v2 changes only the version; loaders validate wire data.
54:         if (ver < 2)
55:         {
56: 			LFPG_Util.Info("[Migrators] Migrating PersistBlob v1 → v2");
57:             ver = 2;
58:         }
59: 
60:         // Future: if (ver < 3) { MigrateV2ToV3(blob); ver = 3; }
61: 
62:         blob.ver = ver;
63:         return ver;
64:     }
65: 
66:     // Apply all necessary migrations to a VanillaWireStore.
67:     static int MigrateVanillaStore(LFPG_VanillaWireStore store)
68:     {
69:         if (!store)
70:             return LFPG_VANILLA_PERSIST_VER;
71: 
72:         int ver = store.ver;
73: 
74:         if (ver > LFPG_VANILLA_PERSIST_VER)
75:         {
76:             LFPG_Util.Warn("[Migrators] VanillaStore ver " + ver.ToString() + " > current " + LFPG_VANILLA_PERSIST_VER.ToString() + ". Loading tolerantly.");
77:             return ver;
78:         }
79: 
80:         if (ver < 2)
81:         {
82: 			LFPG_Util.Info("[Migrators] Migrating VanillaWireStore v1 → v2");
83:             ver = 2;
84:         }
85: 
86:         store.ver = ver;
87:         return ver;
88:     }
89: };
